import numpy as np, matplotlib; matplotlib.use('Agg')
import hypertools as hyp
rng = np.random.default_rng(7)
X = np.vstack([rng.normal(loc=m, scale=1.0, size=(5, 384)) for m in (0, 3, 6, 9)])
def coords(fig):
    import numpy as np
    return np.vstack([np.array(ln.get_data_3d()).T for ln in fig.axes[0].lines if len(ln.get_data()[0])])
f1 = hyp.plot(X, 'o', reduce='UMAP', show=False); f2 = hyp.plot(X, 'o', reduce='UMAP', show=False)
print('unseeded identical:', np.allclose(coords(f1), coords(f2)))
spec = {'model': 'UMAP', 'kwargs': {'random_state': 42}}
f3 = hyp.plot(X, 'o', reduce=spec, show=False); f4 = hyp.plot(X, 'o', reduce=spec, show=False)
print('seeded identical:', np.allclose(coords(f3), coords(f4)))"

